```ts
export function ordenarPorDescuento(subtotalCentavos: number, cupones: Cupon[]): Cupon[] {
  return [...cupones].sort(
    (a, b) => calcularDescuento(subtotalCentavos, b) - calcularDescuento(subtotalCentavos, a),
  );
}
```

